UPDATE nbpuask.conversations
SET conversation_id=#{conversationId}, conversation_user_id=#{conversationUserId}, conversation_available=#{conversationAvailable},
    conversation_data=#{conversationData, jdbcType=OTHER, typeHandler=me.Ailety.NbpuAsk.handler.JsonTypeHandler}
    WHERE conversation_id=#{conversationId} AND conversation_user_id=#{conversationUserId}
